# Script generated for node Custom Transform
def MyTransform(glueContext, dfc) -> DynamicFrameCollection:
    from pyspark.sql import functions as F
    from awsglue.dynamicframe import DynamicFrame, DynamicFrameCollection

    # Recupera o DynamicFrame que entrou no Custom Transform
    df = dfc.select(list(dfc.keys())[0]).toDF()

    regras = {
        "ai_generativa_e_llm_prioridade": F.when(
            F.col("ai_generativa_e_llm_prioridade") ==
            "Mais ou menos... É uma das várias iniciativas que estamos impulsionando, mas não é uma prioridade (tratam-se de iniciativas isoladas e com pouco foco).",
            "Mais ou menos... É uma das várias iniciativas que estamos impulsionando, mas não é uma prioridade (iniciativas isoladas e pouco foco)."
        ).otherwise(F.col("ai_generativa_e_llm_prioridade")),

        "area_formacao": F.when(
            F.col("area_formacao").isin(
                "Ciências Sociais",
                "Marketing / Publicidade / Comunicação / Jornalismo"
            ),
            "Marketing / Publicidade / Comunicação / Jornalismo / Ciências Sociais"
        ).otherwise(F.col("area_formacao")),

        "cargo_atual": F.when(
            F.col("cargo_atual") ==
            "Engenheiro de Dados/Arquiteto de Dados/Data Engineer/Data Architect",
            "Engenheiro de Dados/Data Engineer/Data Architect"
        ).otherwise(F.col("cargo_atual")),

        "faixa_salarial": F.when(
            F.col("faixa_salarial") ==
            "de R$ 101/mês a R$ 2.000/mês",
            "de R$ 1.001/mês a R$ 2.000/mês"
        ).when(
            F.col("faixa_salarial") ==
            "de R$ 25.001/mês a R$ 3000/mês",
            "de R$ 25.001/mês a R$ 30.000/mês"
        ).otherwise(F.col("faixa_salarial")),

        "numero_de_funcionarios": F.when(
            F.col("numero_de_funcionarios") == "de 501 a 100",
            "de 501 a 1.000"
        ).otherwise(F.col("numero_de_funcionarios")),

        "participou_de_entrevistas_ultimos_6m": F.when(
            F.col("participou_de_entrevistas_ultimos_6m") ==
            "Sim, fiz entrevistas mas não fui aprovado",
            "Sim, fiz entrevistas mas não fui aprovado (ou ainda aguardo resposta)"
        ).otherwise(F.col("participou_de_entrevistas_ultimos_6m")),

        "regiao_de_origem": F.when(
            F.col("regiao_de_origem").isin(
                "Espírito Santo (ES)",
                "Minas Gerais (MG)",
                "Rio de Janeiro (RJ)",
                "São Paulo (SP)"
            ),
            "Sudeste"
        ).when(
            F.col("regiao_de_origem").isin(
                "Paraná (PR)",
                "Rio Grande do Sul (RS)",
                "Santa Catarina (SC)"
            ),
            "Sul"
        ).when(
            F.col("regiao_de_origem").isin(
                "Alagoas (AL)",
                "Bahia (BA)",
                "Ceará (CE)",
                "Maranhão (MA)",
                "Paraíba (PB)",
                "Pernambuco (PE)",
                "Piauí (PI)",
                "Rio Grande do Norte (RN)",
                "Sergipe (SE)"
            ),
            "Nordeste"
        ).when(
            F.col("regiao_de_origem").isin(
                "Acre (AC)",
                "Amapá (AP)",
                "Amazonas (AM)",
                "Pará (PA)",
                "Rondônia (RO)",
                "Roraima (RR)",
                "Tocantins (TO)"
            ),
            "Norte"
        ).when(
            F.col("regiao_de_origem").isin(
                "Distrito Federal (DF)",
                "Goiás (GO)",
                "Mato Grosso (MT)",
                "Mato Grosso do Sul (MS)"
            ),
            "Centro-oeste"
        ).otherwise(F.col("regiao_de_origem")),
        
        "tempo_de_experiencia_em_dados": F.when(
            F.col("tempo_de_experiencia_em_dados") == "de 4 a 6 anos",
            "de 5 a 6 anos"
        ).otherwise(F.col("tempo_de_experiencia_em_dados")),
        
        "atuacao_em_dados": F.when(
            (F.col("ano_pesquisa") == "2025") & 
            (F.col("funcao_de_atuacao") == "*Ciência de Dados/Machine Learning/AI: *Desenha e executa experimentos com o objetivo de responder perguntas do negócio; desenvolve modelos e algoritmos de Machine Learning ou AI Generativa com o objetivo de otimizar e automatizar a tomada de decisão;"),
            "Ciência de Dados"
        ).otherwise(F.col("atuacao_em_dados")),
        
        "funcao_de_atuacao": F.when(
            F.col("funcao_de_atuacao") == "*Ciência de Dados/Machine Learning/AI: *Desenha e executa experimentos com o objetivo de responder perguntas do negócio; desenvolve modelos preditivos e algoritmos de Machine Learning com o objetivo de otimizar e automatizar a tomada de decisão.",
            "*Ciência de Dados/Machine Learning/AI: *Desenha e executa experimentos com o objetivo de responder perguntas do negócio; desenvolve modelos e algoritmos de Machine Learning ou AI Generativa com o objetivo de otimizar e automatizar a tomada de decisão;"
        ).otherwise(F.col("funcao_de_atuacao")),
    }

    # Aplica todas as transformações
    df_tratado = df.withColumns(regras)

    # Converte novamente para DynamicFrame
    dyf_tratado = DynamicFrame.fromDF(
        df_tratado,
        glueContext,
        "dyf_tratado"
    )

    # Retorna para o fluxo do Glue
    return DynamicFrameCollection(
        {"CustomTransform0": dyf_tratado},
        glueContext
    )
